#!/usr/bin/env bash
# Submit 9 mini-films: 3 Adiyogi follow-ups, 3 simplistic Krishna, 3 Saint Dnyaneshwar.
# All Wan22 pipeline, drains FIFO via queue scanner.
set -euo pipefail
BACKEND="${BACKEND_URL:-http://localhost:8002}"

post() {
    local title="$1" story="$2" dur="$3"
    local resp id
    resp=$(curl -sf -X POST "$BACKEND/api/projects" -H "Content-Type: application/json" \
        -d "$(python3 -c "import json,sys; print(json.dumps({
            'title': '$title',
            'original_story_text': sys.stdin.read(),
            'total_target_duration_seconds': $dur,
            'pipeline_profile': 'wan22_text_only',
        }))" <<< "$story")")
    id=$(python3 -c "import json,sys; print(json.loads(sys.stdin.read())['id'])" <<< "$resp")
    echo "  $title -> $id"
}

echo "=== Submitting 9 mythology mini-films (Wan22) ==="

# ── Adiyogi follow-ups ─────────────────────────────────────────────────────
post "ad_12_adiyogi_saptarishis" "A 30-second mini-film. Adiyogi — Shiva in his splendid human form, tall bronze-skinned male, long matted jata locks, three horizontal bands of sacred ash (vibhuti) on forehead and chest, closed third eye, crescent moon in hair, snake (Vasuki) at neck, rudraksha mala, tiger-skin loincloth — transmits the yogic sciences to the Saptarishis (Seven Sages) at Kanti Sarovar above Kedarnath. Seven seated sages — bearded, in plain ochre dhotis, hair tied in knots, deeply attentive faces — sit in a semicircle on the snow-dusted shore of a glacial lake at sunrise. Scene 1 (6s, wide establishing): Kanti Sarovar at dawn — frozen alpine lake mirroring the surrounding peaks, prayer flags, mist. The seven sages already seated in semicircle. Camera 60-80 ft, slow push-in. Mood: ancient, sacred. Scene 2 (6s, mid arrival): Adiyogi sits cross-legged on a flat boulder facing them, back perfectly straight, eyes half-open in a meditative gaze, hands in chin mudra resting on his knees. Camera 25-30 ft, three-quarter. Mood: presence, transmission. Scene 3 (6s, sage close-up): Tight close-up of one of the sages — eyes closed, single tear running down cheek, expression of receiving knowledge. Faint golden light on his face. Camera 4 ft, shallow depth-of-field. Mood: revelation. Scene 4 (6s, transmission wide): Subtle golden light arcs from Adiyogi's brow toward the sages' brows. The lake surface ripples once. Snowflakes drift. Camera 20-30 ft, side angle. Mood: cosmic. Scene 5 (6s, final): All seven sages bow forward in pranam, foreheads to the cold stone. Adiyogi remains seated, eyes now fully open, gaze on the rising sun. Camera 30-40 ft, low angle. Mood: completion, lineage born. Consistency: SAME Adiyogi figure and SAME seven sages across scenes; SAME Kanti Sarovar setting; cold blue-gold palette." 30

post "ad_13_adiyogi_ganga" "A 24-second mini-film. Adiyogi — Shiva in human form, tall bronze-skinned, long matted jata locks tied loosely on top of his head, sacred ash bands on forehead and chest, closed third eye, crescent moon in hair, snake at neck, rudraksha mala, tiger-skin loincloth — receives the descending river Ganga into his matted locks to spare the earth from her thunderous fall. Setting: a high Himalayan ridge at dusk, sky deep indigo with first stars, snowy peaks behind. Scene 1 (6s, wide setup): Adiyogi stands tall on a granite outcrop, arms slightly out, head tilted upward, looking at the sky. Below him, the curve of the earth visible. Camera 50-60 ft, low angle. Mood: anticipation. Scene 2 (6s, descent wide): A massive cascading column of luminous turquoise water descends from the upper sky toward his head, spiraling, slowed by the air around him. Camera 40 ft, wide. Mood: cosmic, monumental. Scene 3 (6s, impact close): Tight close-up of his head and matted locks as the column of water enters and is absorbed into the strands, foaming and roiling within the jata. Spray, mist, golden particles. Camera 6 ft. Mood: containment, divinity. Scene 4 (6s, release wide): A single gentle stream of glowing water emerges from one strand of his hair and flows down the rock to begin its earthly journey as a river. Adiyogi unchanged, calm, looking down at the new stream. Camera 25-30 ft, side angle. Mood: birth of a river, mercy. Consistency: SAME Adiyogi figure across all four scenes; SAME Himalayan ridge setting; cool indigo/turquoise/gold palette." 24

post "ad_14_adiyogi_nataraja" "An 18-second mini-film. Adiyogi — Shiva — in the cosmic dance form of Nataraja: tall bronze figure, four arms (upper-right holding a damaru drum, upper-left holding a small flame, lower-right in abhaya mudra fearless gesture, lower-left pointing across body to the raised foot), right foot pressing down a small demon figure (Apasmara) symbolizing ignorance, left leg lifted across the body, surrounded by a ring of cosmic fire. Matted jata flying outward, snake at neck, crescent moon, third eye glowing, anklets, dhoti. Setting: an empty primordial void — black background dusted with stars, a circular halo of orange-gold flame surrounding him. Scene 1 (6s, mid wide): Adiyogi mid-dance, frozen in the iconic Nataraja pose, flame ring slowly rotating around him. Camera 15-20 ft, frontal. Mood: cosmic, eternal. Scene 2 (6s, close drum): Tight close-up of the upper-right hand spinning the damaru drum — small drum twirling, two beads striking each side, sound waves visible as faint blue ripples. Camera 3 ft. Mood: rhythm of creation. Scene 3 (6s, full body rotating): Slow orbit around the full Nataraja figure, flame ring rotating, his pose unchanging, sparks drifting off into the cosmic void. Camera 20 ft, slow rotation. Mood: eternal dance. Consistency: SAME pose across all three scenes (do not change limb positions); SAME flame ring; black-cosmic-with-orange-gold palette." 18

